using System.Collections.Concurrent;
using System.Diagnostics;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal sealed partial class CombatBeamSolver
{
    // Temporary read-only observer. It never removes an action or changes a budget.
    private PotionInventoryOpportunity? _potionInventoryOpportunity;
    private PotionInventoryOpportunity InventoryOpportunity => _potionInventoryOpportunity ??= new(
        root.UsesComponentHealingCertificate && (_smartPotionEligibilityHpCeiling is not null
            || _potionEligibilityObservationBaseline is { Won: true, DeathSaveUseCount: 0 }),
        _minimumPotionUses, (_potionEligibilityObservationBaseline ?? _potionFreePolicyBaseline)?.HpDeficit ?? 0,
        root.PotionRewardOutlook.ReplacementHpCredit, _strategicBossHpRelief,
        root.SearchablePotions.OrderBy(potion => potion.StrategicHpCost)
            .ThenBy(potion => potion.Slot).ToArray());

    private (string Reason, bool Rejected) ObservePotionInventoryOpportunity(
        SearchNode parent, PlanAction action)
    {
        PotionInventoryOpportunity observer = InventoryOpportunity;
        if (!observer.Enabled)
            return ("policy-or-certificate", false);
        SimulationSnapshot snapshot = parent.Snapshot;
        int healing = RemainingHealingPotential(snapshot);
        if (healing == int.MaxValue)
            return ("unknown-branch", false);
        int explicitUsed = ExplicitPotionUseCount(parent);
        int required = observer.ExactUses > 0 ? observer.ExactUses - explicitUsed : 1;
        if (required <= 0 || snapshot.ExplicitPotionStrategicCost < 0)
            return ("count-or-cost", false);
        SimulatedCombatState combat = (SimulatedCombatState)
            ((CombatPredictionSimulator)snapshot.Simulator).State.CombatState;
        SearchablePotionSlotSnapshot? proposed = null;
        foreach (SearchablePotionSlotSnapshot potion in observer.OrderedPotions)
            if (potion.Slot == action.PotionSlot && potion.PotionId == action.PotionId)
                proposed = potion;
        if (proposed is not { } selected)
            return ("unknown-proposed-slot", false);
        // This check detects branch inventory substitutions/free acquisition. The
        // native acquisition closure is an additional premise, not implied by HP=0.
        for (int slot = 0; slot < root.PotionSlotCount; slot++)
        {
            var held = combat.GetPotionAtSlot(_player, slot);
            if (held is null)
                continue;
            if (combat.IsFreeEntropicPotionAtSlot(_player, slot)
                || !observer.OrderedPotions.Any(potion => potion.Slot == slot
                    && potion.PotionId == held.Id.Entry))
                return ("unknown-inventory", false);
        }
        long cost = snapshot.ExplicitPotionStrategicCost + (long)selected.StrategicHpCost;
        required--;
        foreach (SearchablePotionSlotSnapshot potion in observer.OrderedPotions)
        {
            if (required == 0)
                break;
            if (potion.Slot == selected.Slot
                || !AllowsPotionUse(potion.Slot, potion.PotionId)
                || combat.GetPotionAtSlot(_player, potion.Slot)?.Id.Entry != potion.PotionId)
                continue;
            cost += potion.StrategicHpCost;
            required--;
        }
        if (required > 0)
            return ("insufficient-legal-inventory", true);
        if (cost is < 0 or > int.MaxValue)
            return ("cost-overflow", false);
        int ceiling = observer.BaselineHp - PotionUsePolicy.SmartRequiredHpSaved(
            PotionUsePolicy.ApplyReplacementCredit((int)cost,
                observer.ExactUses > 0 ? observer.ExactUses : explicitUsed + 1, observer.ReplacementCredit),
            observer.BossRelief);
        return ("finite", StrategicHpLowerBound(snapshot, observer.BossRelief, healing) > ceiling);
    }

    private void EmitPotionInventoryOpportunity()
    {
        if (_potionInventoryOpportunity is not { } observer)
            return;
        foreach (var entry in observer.Rows.OrderBy(entry => entry.Key, StringComparer.Ordinal))
        {
            PotionInventoryOpportunity.Row row = entry.Value;
            policy.Diagnostics.Info($"[CombatSolver/Test] POTION_INVENTORY_OPPORTUNITY "
                + $"exact={observer.ExactUses} key={entry.Key} preparations={row.Preparations} "
                + $"would_reject={row.Rejected} choice_options={row.Choices} "
                + $"rejected_choice_options={row.RejectedChoices} "
                + $"preparation_ms={row.PreparationTicks * 1000d / Stopwatch.Frequency:R} "
                + $"rejected_preparation_ms={row.RejectedPreparationTicks * 1000d / Stopwatch.Frequency:R} "
                + $"bound_ms={row.BoundTicks * 1000d / Stopwatch.Frequency:R} "
                + $"replays={row.Replays} rejected_replays={row.RejectedReplays} "
                + $"replay_ms={row.ReplayTicks * 1000d / Stopwatch.Frequency:R} "
                + $"rejected_replay_ms={row.RejectedReplayTicks * 1000d / Stopwatch.Frequency:R} "
                + $"replay_bound_ms={row.ReplayBoundTicks * 1000d / Stopwatch.Frequency:R}");
        }
    }

    private sealed class PotionInventoryOpportunity(bool enabled, int exactUses, int baselineHp,
        int replacementCredit, BossHpRelief bossRelief, SearchablePotionSlotSnapshot[] orderedPotions)
    {
        public bool Enabled { get; } = enabled;
        public int ExactUses { get; } = exactUses;
        public int BaselineHp { get; } = baselineHp;
        public int ReplacementCredit { get; } = replacementCredit;
        public BossHpRelief BossRelief { get; } = bossRelief;
        public SearchablePotionSlotSnapshot[] OrderedPotions { get; } = orderedPotions;
        public ConcurrentDictionary<string, Row> Rows { get; } = new(StringComparer.Ordinal);
        public void Record(string potion, string reason, bool rejected, long boundTicks, long ticks, int choices)
        {
            Row row = Rows.GetOrAdd(potion + "/" + reason, static _ => new());
            Interlocked.Increment(ref row.Preparations);
            Interlocked.Add(ref row.Choices, choices);
            Interlocked.Add(ref row.BoundTicks, boundTicks);
            Interlocked.Add(ref row.PreparationTicks, ticks);
            if (!rejected)
                return;
            Interlocked.Increment(ref row.Rejected);
            Interlocked.Add(ref row.RejectedChoices, choices);
            Interlocked.Add(ref row.RejectedPreparationTicks, ticks);
        }
        public void RecordReplay(string potion, string reason, bool rejected, long boundTicks, long ticks)
        {
            Row row = Rows.GetOrAdd(potion + "/" + reason, static _ => new());
            Interlocked.Increment(ref row.Replays);
            Interlocked.Add(ref row.ReplayTicks, ticks);
            Interlocked.Add(ref row.ReplayBoundTicks, boundTicks);
            if (rejected)
            {
                Interlocked.Increment(ref row.RejectedReplays);
                Interlocked.Add(ref row.RejectedReplayTicks, ticks);
            }
        }
        public sealed class Row
        {
            public long Preparations, Rejected, Choices, RejectedChoices, BoundTicks,
                PreparationTicks, RejectedPreparationTicks, Replays, RejectedReplays,
                ReplayTicks, RejectedReplayTicks, ReplayBoundTicks;
        }
    }
}

