import itertools
import json
from pathlib import Path

# Independent enumeration of completions, not a simulator or native contract.
counts = {'exactForcedPotionCases': 0, 'anyUseCompletionCases': 0,
          'rewardCreditMonotonicPairs': 0, 'infeasibleExactCases': 0}

def credited(cost, count, credit):
    return max(1, cost-credit) if cost > 0 and count > 0 and credit > 0 else cost

for size in range(1, 5):
    for costs in itertools.product([0, 9, 14, 18], repeat=size):
        for mask in range(1, 1 << size):
            legal = [i for i in range(size) if mask & (1 << i)]
            for chosen in legal:
                rest = [i for i in legal if i != chosen]
                for spent in [0, 9, 18, 27]:
                    for used in [0, 1, 2]:
                        for exact in range(used+1, used+size+2):
                            needed = exact-used-1
                            completions = [spent + costs[chosen] + sum(costs[i] for i in subset)
                                           for subset in itertools.combinations(rest, needed)]
                            if not completions:
                                counts['infeasibleExactCases'] += 1
                                continue
                            floor = spent + costs[chosen] + sum(sorted(costs[i] for i in rest)[:needed])
                            assert floor == min(completions)
                            counts['exactForcedPotionCases'] += 1
                            for actual in completions:
                                for credit in [0, 6, 14, 30]:
                                    assert credited(floor, exact, credit) <= credited(actual, exact, credit)
                                    counts['rewardCreditMonotonicPairs'] += 1
                        # An unconstrained Smart continuation need not choose the
                        # same final count as another route. Committed cost alone
                        # bounds every continuation, including zero-cost bottles.
                        floor = spent + costs[chosen]
                        for extra in range(len(rest)+1):
                            for subset in itertools.combinations(rest, extra):
                                actual = floor + sum(costs[i] for i in subset)
                                for credit in [0, 6, 14, 30]:
                                    assert credited(floor, used+1, credit) <= credited(actual, used+1+extra, credit)
                                    counts['anyUseCompletionCases'] += 1

result = {'status': 'Passed', 'counts': counts,
          'scope': 'Finite nonnegative prices, distinct legal initial slots, forced next potion, exact and any-use completions.',
          'notProven': ['Native acquisition closure', 'Callbacks', 'RNG/Fork/live isolation',
                        'HP lower bound', 'Whole Coordinator quality or performance'],
          'counterexamplesToMissingPremises': [
              {'case': 'new cheaper potion appears before exact second use',
               'closedInventoryFloor': 36, 'possibleActualCost': 27,
               'reason': 'Chosen price 18 plus old remaining price 18; acquired price 9 invalidates exact distinct-slot floor.'},
              {'case': 'proposed held potion is free Entropic output',
               'nominalFloor': 18, 'actualCommittedCost': 0,
               'reason': 'Nominal catalog price cannot substitute for branch free-acquisition state.'}]}
Path(__file__).with_name('inventory-cost-oracle.json').write_text(json.dumps(result, indent=2)+'\n')
print(json.dumps(result['counts']))
